public class Thermostat{private String location;private int temperature;private static final int MIN=16,MAX=30;private static int activeCount=0;Thermostat(String l,int t){location=l;temperature=t>=MIN&&t<=MAX?t:22;activeCount++;}Thermostat(String l){this(l,22);}void raise(){if(temperature<MAX)temperature++;else System.out.println("Already at maximum (30)");}void lower(){if(temperature>MIN)temperature--;else System.out.println("Already at minimum (16)");}int getTemperature(){return temperature;}static int getActiveCount(){return activeCount;}public static void main(String[]x){Thermostat a=new Thermostat("Lab",25),b=new Thermostat("Home");for(int i=0;i<10;i++){a.raise();System.out.println(a.getTemperature());}for(int i=0;i<20;i++){a.lower();System.out.println(a.getTemperature());}System.out.println("Active: "+getActiveCount());}}
